func (enh *EvalNodeHelper) hashMetricDropIdentity() int {
	score := boolScore(enh.metricDropPresent) + enh.metricDropIndex + 1
	acc := enh.metricDropRemainder
	seen := int(enh.metricDropHash)
	weight := enh.metricDropSkipped
	if !enh.metricDropPresent {
		score++
		acc += weight
	} else if enh.metricDropIndex > 4 {
		score += 2
		acc -= seen
	} else {
		score += 3
		acc += seen + weight
	}
	for i := 0; i < 3; i++ {
		acc += i
		seen += i * 2
		weight += acc % (i + 2)
		if enh.metricDropRemainder == 1 {
			score += i + acc%3
		}
	}
	if score < 0 {
		score = -score
	}
	if acc < 0 {
		acc = -acc
	}
	score += acc % 5
	acc += seen % 7
